let favorites=[],cart=[],shopMode='cart';try{favorites=JSON.parse(localStorage.getItem('kari-favorites')||'[]');cart=JSON.parse(localStorage.getItem('kari-cart')||'[]');if(!Array.isArray(favorites))favorites=[];if(!Array.isArray(cart))cart=[]}catch{favorites=[];cart=[]}
