function favoriteButton(p){const yes=favorites.includes(p.id);return `<button class="favorite-button ${yes?'is-saved':''}" data-favorite="${p.id}" aria-pressed="${yes}" aria-label="${shopCopy[lang][yes?'unsave':'saved']}: ${escapeHTML(p[lang])}">${heart}</button>`}
function persistShop(){try{localStorage.setItem('kari-cart',JSON.stringify(cart));localStorage.setItem('kari-favorites',JSON.stringify(favorites))}catch{}renderShop()}
function toast(message){$('#shop-toast').textContent=message;$('#shop-toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#shop-toast').classList.remove('visible'),2200)}
function renderShop(){const c=shopCopy[lang];$('#open-cart').setAttribute('aria-label',c.cart);$('#open-favorites').setAttribute('aria-label',c.favorites);$('#cart-count').textContent=cart.reduce((n,x)=>n+x.qty,0)||'';$('#favorite-count').textContent=favorites.length||'';$('#shop-title').textContent=c[shopMode];let total=0;const list=shopMode==='favorites'?products.filter(p=>favorites.includes(p.id)).map(p=>`<div class="saved-row"><button data-open-product="${p.id}"><img src="${p.image}" alt=""><span>${escapeHTML(p[lang])}<small>${price(p)}</small></span></button>${favoriteButton(p)}</div>`):cart.map((x,index)=>{const p=products.find(p=>p.id===x.product),v=p?.variants.find(v=>v.id===x.variant);if(!v)return '';total+=v.price*x.qty;return `<div class="cart-row"><img src="${p.image}" alt=""><div><button class="cart-product-name" data-open-product="${p.id}">${escapeHTML(p[lang])}</button><small>${escapeHTML(v[lang])}${x.pillow?' · '+escapeHTML(x.pillow):''}</small><strong>${money(v.price*x.qty)}</strong><div class="quantity"><button data-quantity="${index}" data-delta="-1" aria-label="${c.less}" ${x.qty<=1?'disabled':''}>−</button><span>${x.qty}</span><button data-quantity="${index}" data-delta="1" aria-label="${c.more}" ${x.qty>=v.stock?'disabled':''}>+</button><button class="remove-item" data-remove="${index}">${c.remove}</button></div></div></div>`});$('#shop-content').innerHTML=list.length?list.join(''):`<p class="shop-empty">${c.empty}</p>`;$('#shop-total').innerHTML=shopMode==='cart'&&list.length?`<div><span>${c.total}</span><strong>${money(total)}</strong></div><p>${c.note}</p>`:''}
function openShop(mode){shopMode=mode;renderShop();$('#shop-dialog').showModal()}
document.addEventListener('click',e=>{const f=e.target.closest('[data-favorite]');if(f){const id=f.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persistShop();document.querySelectorAll('[data-favorite]').forEach(b=>{const yes=favorites.includes(b.dataset.favorite);b.classList.toggle('is-saved',yes);b.setAttribute('aria-pressed',yes);const p=products.find(p=>p.id===b.dataset.favorite);b.setAttribute('aria-label',shopCopy[lang][yes?'unsave':'saved']+': '+p[lang])});return}if(e.target.closest('[data-add-cart]')){const p=activeProduct,v=p.variants.find(v=>v.id===selectedVariant),pillow=$('.pillow-label select')?.value||'',existing=cart.find(x=>x.product===p.id&&x.variant===v.id&&x.pillow===pillow),used=cart.filter(x=>x.variant===v.id).reduce((n,x)=>n+x.qty,0);if(used>=v.stock)return toast(shopCopy[lang].limit);if(existing)existing.qty++;else cart.push({product:p.id,variant:v.id,pillow,qty:1});persistShop();toast(shopCopy[lang].added)}const q=e.target.closest('[data-quantity]');if(q){const x=cart[+q.dataset.quantity],p=products.find(p=>p.id===x.product),v=p.variants.find(v=>v.id===x.variant),used=cart.filter(y=>y.variant===x.variant).reduce((n,y)=>n+y.qty,0),delta=+q.dataset.delta;if(delta>0&&used>=v.stock)return toast(shopCopy[lang].limit);x.qty=Math.max(1,x.qty+delta);persistShop()}const rm=e.target.closest('[data-remove]');if(rm){cart.splice(+rm.dataset.remove,1);persistShop()}const op=e.target.closest('[data-open-product]');if(op){$('#shop-dialog').close();detail(products.find(p=>p.id===op.dataset.openProduct));$('#product-dialog').showModal();$('#product-dialog').scrollTop=0}});
$('#open-cart').addEventListener('click',()=>openShop('cart'));$('#open-favorites').addEventListener('click',()=>openShop('favorites'));$('#close-shop').addEventListener('click',()=>$('#shop-dialog').close());$('#shop-dialog').addEventListener('click',e=>{if(e.target===$('#shop-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function links(){return categories.map((c,i)=>`<a href="#catalog/${c[0]}" class="${i>0&&i<7?'sub ':''}${category===c[0]?'active':''}" ${category===c[0]?'aria-current="true"':''}>${name(c[0])}</a>`).join('')}
function matching(p){if(category==='bedding')return subs.includes(p.category);if(category==='new')return p.new;if(category==='linen-new')return subs.includes(p.category)&&p.new;return p.category===category}
