function unusedFrameComposition(t){const points=[[0,56],[3.9,56],[5,94],[6.7,94],[8,65],[10.5,65],[11.8,35],[13.8,35],[15,57],[17.5,57],[18.8,54],[20.8,54],[22,94],[24.1,94],[25,56]];let x=56;for(let i=1;i<points.length;i++){if(t<=points[i][0]){const [a,ax]=points[i-1],[b,bx]=points[i];const q=Math.max(0,Math.min(1,(t-a)/(b-a)));const smooth=q*q*(3-2*q);x=ax+(bx-ax)*smooth;break}}story.style.setProperty('--subject-x',x+'%')}
function timeFromProgress(p){if(!mobileQuery.matches)return p*25;for(let i=1;i<timeline.length;i++){const [p1,t1]=timeline[i], [p0,t0]=timeline[i-1];if(p<=p1)return t0+(p-p0)/(p1-p0)*(t1-t0)}return 25}
function progressFromTime(t){if(!mobileQuery.matches)return t/25;for(let i=1;i<timeline.length;i++){const [p1,t1]=timeline[i], [p0,t0]=timeline[i-1];if(t<=t1&&t1>t0)return p0+(t-t0)/(t1-t0)*(p1-p0)}return 1}
function getProgress(){if(reduced)return 0;return Math.max(0,Math.min(1,-story.getBoundingClientRect().top/Math.max(1,story.offsetHeight-innerHeight)))}
function update(){const p=getProgress();$('#progress').style.width=`${p*100}%`;story.dataset.phase=p<.075?'opening':p>.93?'final':'motion';if(player)player.seek(timeFromProgress(p))}
const loadText={uk:'Завантаження фрагмента…',ru:'Загрузка фрагмента…',en:'Loading this scene…'};
function mediaState(state){$('#video-loading').hidden=state!=='loading';$('#video-loading').textContent=loadText[lang];$('#video-error').hidden=state!=='error';$('#retry-video').hidden=state!=='error';story.dataset.mediaState=state}
function initMedia(){player?.destroy();player=null;reduced=motionQuery.matches;document.documentElement.classList.toggle('reduced-motion',reduced);mediaState('ready');if(reduced){renderedStoryTime=0;setScene(0,true);story.dataset.phase='opening';return}player=new StoryPlayer({videos:[video,$('#hero-next')],onFrame:t=>{renderedStoryTime=t;story.dataset.frameTime=t.toFixed(3);setScene(t)},onState:mediaState});player.start();update()}
$('#retry-video').addEventListener('click',()=>player?.retry());
addEventListener('scroll',update,{passive:true});addEventListener('resize',update);motionQuery.addEventListener('change',initMedia);
$('#chapters').addEventListener('click',e=>{const b=e.target.closest('[data-scene]');if(!b)return;const s=scenes[Number(b.dataset.scene)];window.scrollTo({top:story.offsetTop+progressFromTime(s.time+(s.time?1:0))*(story.offsetHeight-innerHeight),behavior:reduced?'instant':'smooth'})});
$$('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;try{localStorage.setItem('karisan-language',lang)}catch{}translate();$('#language-options').hidden=true;$('#language-button').setAttribute('aria-expanded','false')}));
const menu=$('#menu');mobileQuery.addEventListener('change',update);$('#menu-button').addEventListener('click',()=>{menu.showModal();document.documentElement.classList.add('menu-open');$('#close-menu').focus();$('#menu-button').setAttribute('aria-expanded','true')});$('#close-menu').addEventListener('click',()=>menu.close());menu.addEventListener('close',()=>{document.documentElement.classList.remove('menu-open');$('#menu-button').setAttribute('aria-expanded','false');$('#menu-button').focus({preventScroll:true})});menu.addEventListener('click',e=>{if(e.target.closest('a'))menu.close()});
const languageButton=$('#language-button'),languageOptions=$('#language-options');languageButton.addEventListener('click',()=>{languageOptions.hidden=!languageOptions.hidden;languageButton.setAttribute('aria-expanded',String(!languageOptions.hidden))});document.addEventListener('click',e=>{if(!e.target.closest('.language-picker')){languageOptions.hidden=true;languageButton.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!languageOptions.hidden){languageOptions.hidden=true;languageButton.setAttribute('aria-expanded','false');languageButton.focus()}});
const pd=$('#product-dialog');$('.close-product').addEventListener('click',()=>pd.close());$('#products').addEventListener('click',e=>{const b=e.target.closest('[data-product]');if(!b)return;detail(products.find(p=>p.id===b.dataset.product));pd.showModal();pd.scrollTop=0});pd.addEventListener('close',()=>activeProduct=null);[menu,pd].forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function route(){let id=location.hash.split('/')[1];if(location.hash.startsWith('#catalog')){if(categories.some(c=>c[0]===id))category=id;renderProducts();$('#catalog').scrollIntoView({behavior:'instant'})}}
addEventListener('hashchange',route);document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#catalog"]');if(a&&a.hash===location.hash)route()});
async function loadProducts(){try{const r=await fetch('products.json?v=shop-20260929b');if(!r.ok)throw Error(r.status);products=await r.json();loadFailed=false}catch{loadFailed=true}renderProducts()}
$('#year').textContent=new Date().getFullYear();translate();loadProducts().then(route);initMedia();
